coded allat","","","if not game:IsLoaded() then game.Loaded:Wait() end","","pcall(function()","    if getgenv().Library and getgenv().Library.Unload then","        pcall(getgenv().Library.Unload, getgenv().Library)","    end","    for _, v in ipairs(game:GetService(\"Lighting\"):GetChildren()) do","        if v:IsA(\"BlurEffect\") then v:Destroy() end","    end","end)","","if getgenv().Library and getgenv().Library.Unload then","    pcall(getgenv().Library.Unload, getgenv().Library)","end","","local GetService = setmetatable({}, {","    __index = function(_, Name)","        return game:GetService(Name);","    end;","})","","local Workspace, Players, RunService, HttpService = GetService[\"Workspace\"], GetService[\"Players\"], GetService[\"RunService\"], GetService[\"HttpService\"];","local LocalPlayer, Camera = Players.LocalPlayer, Workspace.CurrentCamera;","local WorldToViewportPoint, FindFirstChildOfClass, FindFirstChild = Camera.WorldToViewportPoint, game.FindFirstChildOfClass, game.FindFirstChild;","","local NewVector3, NewVector2, Dim, Dim2, DimOffset = Vector3.new, Vector2.new, UDim.new, UDim2.new, UDim2.fromOffset;","local NumSeq = NumberSequence.new;","local NumKey = NumberSequenceKeypoint.new;","","local Format, Spawn, Clear, Floor, Clamp, Abs, Tan, Rad, Huge, Remove = string.format, task.spawn, table.clear, math.floor, math.clamp, math.abs, math.tan, math.rad, math.huge, table.remove;","local Frame, ZeroVector3, CameraPosition, CachedFocalLength, ViewPortY, Updates = 1 / 60, NewVector3(0,0,0), NewVector3(0,0,0), 0, 0, 0;","","local function CameraCache()","    ViewPortY = Camera.ViewportSize.Y;","    CachedFocalLength = ViewPortY / (2 * Tan(Rad(Camera.FieldOfView) * 0.5));","end","","CameraCache();","","Camera:GetPropertyChangedSignal(\"FieldOfView\"):Connect(CameraCache);","Camera:GetPropertyChangedSignal(\"ViewportSize\"):Connect(CameraCache);","","getgenv().Library = {","    ['Directory'] = 'Esp',","    ['Cache'] = {},","    ['Holder'] = nil,","    ['Th