e\"] = self:CreateObjects(\"TextLabel\", {","            Parent = Objects[\"BottomTextHolder\"],","            FontFace = Library.SmallestPixel,","            TextSize = 9,","            LayoutOrder = 2,","            TextColor3 = Table['Texts']['Distance']['Color'],","            Text = \"\",","            TextXAlignment = Enum.TextXAlignment.Center,","            BorderSizePixel = 0,","            Visible = false,","            BackgroundTransparency = 1,","            ZIndex = 5,","            AutomaticSize = Enum.AutomaticSize.XY,","            Size = Dim2(0, 0, 0, 0),","        })","","        self:CreateObjects(\"UIStroke\", {","            Parent = Objects[\"Distance\"],","            Color = Color3.fromRGB(0, 0, 0),","            LineJoinMode = Enum.LineJoinMode.Miter,","        })","","        Objects[\"WalkFlag\"] = self:CreateObjects(\"TextLabel\", {","            Parent = Objects[\"RightTextHolder\"],","            FontFace = Library.SmallestPixel,","            TextSize = 9,","            LayoutOrder = 1,","            TextColor3 = Table['Flags']['Walking']['Color'],","            Text = Table['Flags']['Walking']['Text'],","            TextXAlignment = Enum.TextXAlignment.Left,","            BorderSizePixel = 0,","            Visible = false,","            BackgroundTransparency = 1,","            ZIndex = 5,","            AutomaticSize = Enum.AutomaticSize.XY,","            Size = Dim2(0, 0, 0, 0),","        })","","        self:CreateObjects(\"UIStroke\", {","            Parent = Objects[\"WalkFlag\"],","            Color = Color3.fromRGB(0, 0, 0),","            LineJoinMode = Enum.LineJoinMode.Miter,","        })","","        Objects[\"JumpFlag\"] = self:CreateObjects(\"TextLabel\", {","            Parent = Objects[\"RightTextHolder\"],","            FontFace = Library.SmallestPixel,","            TextSize = 9,","            LayoutOrder = 2,","            TextColor3 = Table['Flags']['Jumping']['Color'],","            Text = Table['Flags']['Jumping']['Text'],","            TextXAlignment = Enum.TextXAlignment.Left,","            BorderSizePixel = 0,","            Visible = false,","            BackgroundTransparency = 1,","            ZIndex = 5,","            AutomaticSize = Enum.AutomaticSize.XY,","            Size = Dim2(0, 0, 0, 0),","        })","","        self:CreateObjects(\"UIStroke\", {","            Parent = Objects[\"JumpFlag\"],","            Color = Color3.fromRGB(0, 0, 0),","            LineJoinMode = Enum.LineJoinMode.Miter,","        })","","        Objects[\"SwimmingFlag\"] = self:CreateObjects(\"TextLabel\", {","            Parent = Objects[\"RightTextHolder\"],","            FontFace = Library.SmallestPixel,","            TextSize = 9,","            LayoutOrder = 4,","            TextColor3 = Table['Flags']['Swimming']['Color'],","            Text = Table['Flags']['Swimming']['Text'],","            TextXAlignment = Enum.TextXAlignment.Left,","            BorderSizePixel = 0,","            Visible = false,","            BackgroundTransparency = 1,","            ZIndex = 5,","            AutomaticSize = Enum.AutomaticSize.XY,","            Size = Dim2(0, 0, 0, 0),","        })","","        self:CreateObjects(\"UIStroke\", {","            Parent = Objects[\"SwimmingFlag\"],","            Color = Color3.fromRGB(0, 0, 0),","            LineJoinMode = Enum.LineJoinMode.Miter,","        })","","        Objects[\"Weapon\"] = self:CreateObjects(\"TextLabel\", {","            Parent = Objects[\"BottomTextHolder\"],","            FontFace = Library.SmallestPixel,","            TextSize = 9,","            LayoutOrder = 3,","            TextColor3 = Table['Texts']['Weapon']['Color'],","            Text = \"none\",","            TextXAlignment = Enum.TextXAlignment.Center,","            BorderSizePixel = 0,","            Visible = false,","            BackgroundTransparency = 1,","            ZIndex = 5,","            AutomaticSize = Enum.AutomaticSize.XY,","            Size = Dim2(0, 0, 0, 0),","        })","","        self:CreateObjects(\"UIStroke\", {","            Parent = Objects[\"Weapon\"],","            Color = Color3.fromRGB(0, 0, 0),","            LineJoinMode = Enum.LineJoinMode.Miter,","        })","    end","end","","local CornerLayout = {","    {Dim2(0, -1, 0, -1), Dim2(0.3, 0, 0, 1), NewVector2(0, 0), 0},","    {Dim2(0, -1, 0, -1), Dim2(0, 1, 0.3, 0), NewVector2(0, 0), 180},","    {Dim2(1, 1, 0, -1), Dim2(0.3, 0, 0, 1), NewVector2(1, 0), 0},","    {Dim2(1, 1, 0, -1), Dim2(0, 1, 0.3, 0), NewVector2(1, 0), 180},","    {Dim2(0, -1, 1, 1), Dim2(0.3, 0, 0, 1), NewVector2(0, 1), 0},","    {Dim2(0, -1, 1, 1), Dim2(0, 1, 0.3, 0), NewVector2(0, 1), -180},","    {Dim2(1, 1, 1, 1), Dim2(0.3, 0, 0, 1), NewVector2(1, 1), 0},","    {Dim2(1, 1, 1, 1), Dim2(0, 1, 0.3, 0), NewVector2(1, 1), -180},","}","","function Library:CalculateBox(Data)","    local RootPart = Data['RootPart']","","    if not RootPart then","        return nil, nil, nil, nil, false;","    end;","","    local RootScreen, OnScreen = WorldToViewportPoint(Camera, RootPart.Position)","","    if not OnScreen then","        return nil, nil, nil, nil, false;","    end;","","    local BoundingBox = Table['Boxes']['Bounding Box'];","","    if Table['Boxes']['DynamicBoxes'] then","        local Children = Data['Children'];","","        if not Children then","            return nil, nil, nil, nil, false;","        end;","","        local IncludeAccessories = Data['IncludeAccessories'];","        local ScrMinX, ScrMinY = Huge, Huge;","        local ScrMaxX, ScrMaxY = -Huge, -Huge;","        local HasValidParts = false;","","        for _, Part in Children do","            if Part:IsA('BasePart') and Part.Transparency ~= 1 and Part ~= RootPart then","                local Parent = Part.Parent","","                if Parent == nil then","                    continue","                end","","                if not IncludeAccessories and Parent:IsA('Accessory') then","                    continue;","                end;","","                local PartScreen, PartOnScreen = WorldToViewportPoint(Camera, Part.Position);","","                if not PartOnScreen or PartScreen.Z \u003c= 0 then","                    continue;","                end;","","                HasValidParts = true;","","                local Cf = Part.CFrame;","                local Sz = Part.Size;","                local HX, HY, HZ = Sz.X * 0.5, Sz.Y * 0.5, Sz.Z * 0.5;","                local RX, UY, LZ = Cf.RightVector, Cf.UpVector, Cf.LookVector;","                local DepthScale = CachedFocalLength / PartScreen.Z;","","                local Ex = (Abs(RX.X * HX) + Abs(UY.X * HY) + Abs(LZ.X * HZ)) * DepthScale;","                local Ey = (Abs(RX.Y * HX) + Abs(UY.Y * HY) + Abs(LZ.Y * HZ)) * DepthScale;","","                local PMinX, PMaxX = PartScreen.X - Ex, PartScreen.X + Ex;","                local PMinY, PMaxY = PartScreen.Y - Ey, PartScreen.Y + Ey;","","                if PMinX \u003c ScrMinX then ScrMinX = PMinX; end","                if PMaxX \u003e ScrMaxX then ScrMaxX = PMaxX; end","                if PMinY \u003c ScrMinY then ScrMinY = PMinY; end","                if PMaxY \u003e ScrMaxY then ScrMaxY = PMaxY; end","            end;","        end;","","        if not HasValidParts then","            return nil, nil, nil, nil, false;","        end;","","        local PadX = BoundingBox['BoxX'];","        local PadY = BoundingBox['BoxY'];","        local W = (ScrMaxX - ScrMinX) + PadX;","        local H = (ScrMaxY - ScrMinY) + PadY;","","        return W, H, ScrMinX - (PadX * 0.5), ScrMinY - (PadY * 0.5), true;","    else","        local Scale = (RootPart.Size.Y * ViewPortY) / (RootScreen.Z * 2);","        local W, H = 3 * Scale, 4.5 * Scale;","        return W, H, RootScreen.X - (W * 0.5), RootScreen.Y - (H * 0.5), OnScreen;","    end","end","","function Library:AddTarget(Player)","    if Player == LocalPlayer and not Table['ShowLocalPlayer'] then","        return","    end;","","    if self.Cache[Player] then","        return","    end;","","    local Data = {","        ['Player'] = Player,","        ['Objects'] = {},","        ['Conns'] = {},","        ['Character'] = nil,","        ['RootPart'] = nil,","        ['Humanoid'] = nil,","        ['Children'] = nil,","        ['Health'] = 0,","        ['MaxHealth'] = 100,","        ['Armor'] = 100,","        ['MaxArmor'] = 100,","        ['CurrentTool'] = nil,","        ['Alive'] = false,","        ['LastW'] = nil,","        ['LastH'] = nil,","        ['LastX'] = nil,","        ['LastY'] = nil,","        ['WalkActive'] = false,","        ['JumpActive'] = false,","        ['FallingActive'] = false,","        ['SwimmingActive'] = false,","        ['IncludeAccessories'] = Table['Boxes']['Bounding Box']['IncludeAcsessories'],","        ['LastGlowTop'] = nil,","        ['LastGlowBot'] = nil,","        ['LastGlowT1'] = nil,","        ['LastGlowT2'] = nil,","        ['LastGradTop'] = nil,","        ['LastGradBot'] = nil,","        ['LastFillTop'] = nil,","        ['LastFillBot'] = nil,","        ['LastFillT1'] = nil,","        ['LastFillT2'] = nil,","        ['LastDist'] = nil,","        ['LastDistColor'] = nil,","        ['LastDisplayName'] = nil,","        ['LastNameColor'] = nil,","        ['LastHealthTop'] = nil,","        ['LastHealthMid'] = nil,","        ['LastHealthBot'] = nil,","        ['LastHealthFloor'] = nil,","        ['LastRatio'] = nil,","        ['LastArmorTop'] = nil,","        ['LastArmorMid'] = nil,","        ['LastArmorBot'] = nil,","        ['LastArmorFloor'] = nil,","        ['LastArmorRatio'] = nil,","        ['LastWeapon'] = nil,","        ['LastWeaponColor'] = nil,","    }","    self:InitEsp(Data);","    self['Cache'][Player] = Data;","","    local HealthHandler = {}; do","        function HealthHandler.BindHealth(Humanoid)","            if Data['Conns']['Health'] then","                Data['Conns']['Health']:Disconnect()","            end","","            if Data['Conns']['Died'] then","                Data['Conns']['Died']:Disconnect()","            end","","            Data['Humanoid'] = Humanoid","            Data['Health'] = Humanoid.Health","            Data['MaxHealth'] = Humanoid.MaxHealth","            Data['Alive'] = Humanoid.Health \u003e 0","","            Data['Conns']['Health'] = Humanoid.HealthChanged:Connect(function(NewHealth)","                Data['Alive'] = NewHealth \u003e 0","                Data['Health'] = NewHealth","            end)","","            Data['Conns']['Died'] = Humanoid.Died:Connect(function()","                Data['Alive'] = false","            end)","        end","","        Data['BindHealth'] = HealthHandler.BindHealth;","    end","","    local ToolHandler = {}; do","        function ToolHandler.BindTool(Character)","            if Data['Conns']['ToolAdded'] then","                Data['Conns']['ToolAdded']:Disconnect()","            end","","            if Data['Conns']['ToolRemoved'] then","                Data['Conns']['ToolRemoved']:Disconnect()","            end","","            if Data['Children'] then","                for _, Child in Data['Children'] do","                    if Child:IsA('Tool') then","                        Data['CurrentTool'] = Child.Name","                        break","                    end","                end","            end","","            Data['Conns']['ToolAdded'] = Character.ChildAdded:Connect(function(Child)","                if Child:IsA('Tool') then","                    Data['CurrentTool'] = Child.Name","                end","            end)","","            Data['Conns']['ToolRemoved'] = Character.ChildRemoved:Connect(function(Child)","                if Child:IsA('Tool') then","                    Data['CurrentTool'] = nil","                end","            end)","        end","","        Data['BindTool'] = ToolHandler.BindTool","    end","","    local ChildHandler = {}; do","        function ChildHandler.BindChildren(Character)","            if Data['Conns']['ChildAdded'] then","                Data['Conns']['ChildAdded']:Disconnect();","            end;","","            if Data['Conns']['ChildRemoved'] then","                Data['Conns']['ChildRemoved']:Disconnect();","            end;","","            local Children = Character:GetChildren();","            Data['Children'] = Children;","","            Data['Conns']['ChildAdded'] = Character.ChildAdded:Connect(function(Child)","                Children[#Children + 1] = Child;","            end)","","            Data['Conns']['ChildRemoved'] = Character.ChildRemoved:Connect(function(Child)","                for I = #Children, 1, -1 do","                    if Children[I] == Child then","                        Remove(Children, I);","                        break;","                    end;","                end","            end)","","            Data['BindTool'](Character);","        end","","        Data['BindChildren'] = ChildHandler.BindChildren;","    end","","    local FlagsHandler = {}; do","        function FlagsHandler.BindFlags(Humanoid)","            if Data['Conns']['MoveDir'] then","                Data['Conns']['MoveDir']:Disconnect();","            end;","","            if Data['Conns']['StateChange'] then","                Data['Conns']['StateChange']:Disconnect();","            end;","","            local Objects = Data['Objects']","            Data['JumpActive'] = false;","            Data['WalkActive'] = false;","            Data['FallingActive'] = false;","            Data['SwimmingActive'] = false;","","            Objects['WalkFlag'].Visible = false;","            Objects['JumpFlag'].Visible = false;","            Objects['SwimmingFlag'].Visible = false;","","            Data['Conns']['MoveDir'] = Humanoid:GetPropertyChangedSignal('MoveDirection'):Connect(function()","                local Walking = Humanoid.MoveDirection ~= ZeroVector3;","","                if Walking and not Data['WalkActive'] then","                    Data['WalkActive'] = true;","","                    if Data['JumpActive'] then","                        Objects['WalkFlag'].LayoutOrder = 2;","                    else","                        Objects['WalkFlag'].LayoutOrder = 1;","                        Objects['JumpFlag'].LayoutOrder = 2;","                    end","","                    Objects['WalkFlag'].Visible = Table['Flags']['Walking']['Enabled']","                elseif not Walking and Data['WalkActive'] then","                    Data['WalkActive'] = false;","                    Objects['WalkFlag'].Visible = false;","","                    if Data['JumpActive'] then","                        Objects['JumpFlag'].LayoutOrder = 1;","                    end","                end","            end)","","            Data['Conns']['StateChange'] = Humanoid.StateChanged:Connect(function(_, NewState)","                if NewState == Enum.HumanoidStateType.Freefall and not Data['JumpActive'] then","                    Data['JumpActive'] = true;","","                    if Data['WalkActive'] then","                        Objects['JumpFlag'].LayoutOrder = 2;","                    else","                        Objects['JumpFlag'].LayoutOrder = 1;","                        Objects['WalkFlag'].LayoutOrder = 2;","                    end","","                    Objects['JumpFlag'].Visible = Table['Flags']['Jumping']['Enabled']","                elseif NewState ~= Enum.HumanoidStateType.Jumping and Data['JumpActive'] then","                    Data['JumpActive'] = false;","                    Objects['JumpFlag'].Visible = false;","","                    if Data['WalkActive'] then","                        Objects['WalkFlag'].LayoutOrder = 1;","                    end","                end","","                if NewState == Enum.HumanoidStateType.Swimming and not Data['SwimmingActive'] then","                    Data['SwimmingActive'] = true;","                    Objects['SwimmingFlag'].Visible = Table['Flags']['Swimming']['Enabled']","                elseif NewState ~= Enum.HumanoidStateType.Swimming and Data['SwimmingActive'] then","                    Data['SwimmingActive'] = false;","                    Objects['SwimmingFlag'].Visible = false;","                end","            end)","        end","","        Data['BindFlags'] = FlagsHandler.BindFlags;","    end","","    local CharacterHandler = {}; do","        function CharacterHandler.OnCharacter(Character)","            Data['Character'] = Character;","            Data['RootPart'] = nil;","            Data['Humanoid'] = nil;","            Data['Children'] = nil;","            Data['Alive'] = false;","            Data['WalkActive'] = false;","            Data['JumpActive'] = false;","            Data['FallingActive'] = false;","            Data['SwimmingActive'] = false;","","            if not Character or not Character.Parent then","                return;","            end;","","            local RootPart = FindFirstChild(Character, \"HumanoidRootPart\");","","            if not RootPart then","                RootPart = Character:WaitForChild('HumanoidRootPart', 10);","            end","","            local Humanoid = FindFirstChildOfClass(Character, 'Humanoid');","","            if not Humanoid then","                Humanoid = Character:WaitForChild('Humanoid', 10);","            end;","","            if not RootPart or not Humanoid then","                return;","            end;","","            if not Character.Parent then","                return;","            end;","","            Data['RootPart'] = RootPart;","            Data['Humanoid'] = Humanoid;","","            Data['BindChildren'](Character);","            Data['BindHealth'](Humanoid);","            Data['BindFlags'](Humanoid);","        end","","        Data['Conns']['CharAdded'] = Player.CharacterAdded:Connect(function(Character)","            task.defer(CharacterHandler.OnCharacter, Character)","        end)","","        if Player.Character and Player.Character.Parent then","            task.defer(CharacterHandler.OnCharacter, Player.Character)","        end","    end","end","","function Library:RemoveTarget(Player)","    local Data = self['Cache'][Player];","","    if not Data then","        return;","    end;","","    for _, Connections in Data['Conns'] do","        Connections:Disconnect()","    end;","","    Clear(Data['Conns']);","","    if Data['Objects']['TargetHolder'] then","        Data['Objects']['TargetHolder']:Destroy();","    end;","","    Clear(Data['Objects']);","    self['Cache'][Player] = nil;","end","","function Library:Update(Player, Data)","    local Objects = Data['Objects']","","    -- never draw local player unless show local is on","    if Player == LocalPlayer and not Table['ShowLocalPlayer'] then","        if Objects['TargetHolder'] and Objects['TargetHolder'].Visible then","            Objects['TargetHolder'].Visible = false","        end","        return","    end","","    if not Data['RootPart'] then","        if Objects['TargetHolder'].Visible then","            Objects['TargetHolder'].Visible = false","        end","        return","    end","","    if not Data['Alive'] then","        if Objects['TargetHolder'].Visible then","            Objects['TargetHolder'].Visible = false","        end","        return","    end","","    local RootPos = Data['RootPart'].Position","    local Distance = Floor((CameraPosition - RootPos).Magnitude)","","    if Distance \u003e Table['Distance'] then","        if Objects['TargetHolder'].Visible then","            Objects['TargetHolder'].Visible = false","        end","        return","    end","","    local W, H, X, Y, OnScreen = self:CalculateBox(Data)","","    if not OnScreen or not W then","        if Objects['TargetHolder'].Visible then","            Objects['TargetHolder'].Visible = false","        end","        return","    end","","    W = Floor(W)","    H = Floor(H)","    X = Floor(X)","    Y = Floor(Y)","","    if not Objects['TargetHolder'].Visible then","        Objects['TargetHolder'].Visible = true","    end","","    local DirtySizes = Data['LastW'] ~= W or Data['LastH'] ~= H","    local DirtyPosition = Data['LastX'] ~= X or Data['LastY'] ~= Y","","    if DirtyPosition then","        Objects['TargetHolder'].Position = DimOffset(X, Y)","        Data['LastX'] = X","        Data['LastY'] = Y","    end","","    if DirtySizes then","        Objects['TargetHolder'].Size = DimOffset(W, H)","        Objects['BoxGlow'].Size = DimOffset(W, H)","        Objects['BoxOutlineHolder'].Size = DimOffset(W, H)","        Objects['BoxInlineHolder'].Size = DimOffset(W + 2, H + 2)","        Objects['BoxFill'].Size = DimOffset(W, H)","        Objects['CornerHolder'].Size = DimOffset(W + 2, H + 2)","        Data['LastW'] = W","        Data['LastH'] = H","    end","","    local BoxesCfg = Table['Boxes']","    local TextsCfg = Table['Texts']","","    if BoxesCfg['Enabled'] then","        if BoxesCfg['Box Glow']['Enabled'] then","            if Objects['BoxGlow'].ImageTransparency ~= 0 then","                Objects['BoxGlow'].ImageTransparency = 0","            end","","            local GlowTop = BoxesCfg['Box Glow']['Top']","            local GlowBot = BoxesCfg['Box Glow']['Bot']","","            if Data['LastGlowTop'] ~= GlowTop or Data['LastGlowBot'] ~= GlowBot then","                Objects['BoxGlowGradient'].Color = ColorSequence.new({","                    ColorSequenceKeypoint.new(0, GlowTop),","                    ColorSequenceKeypoint.new(1, GlowBot),","                })","                Data['LastGlowTop'] = GlowTop","                Data['LastGlowBot'] = GlowBot","            end","","            local T1 = BoxesCfg['Box Glow']['Transparency'][1]","            local T2 = BoxesCfg['Box Glow']['Transparency'][2]","","            if Data['LastGlowT1'] ~= T1 or Data['LastGlowT2'] ~= T2 then","                Objects['BoxGlowGradient'].Transparency = NumSeq({NumKey(0, T1), NumKey(1, T2)})","                Data['LastGlowT1'] = T1","                Data['LastGlowT2'] = T2","            end","        else","            if Objects['BoxGlow'].ImageTransparency ~= 1 then","                Objects['BoxGlow'].ImageTransparency = 1","            end","        end","","        local BoxType = BoxesCfg['Type']","","        if BoxType == \"Corner\" then","            if Objects['BoxOutlineHolder'].Visible then","                Objects['BoxOutlineHolder'].Visible = false","            end","            if Objects['BoxInlineHolder'].Visible then","                Objects['BoxInlineHolder'].Visible = false","            end","            if Objects['BoxFill'].Visible then","                Objects['BoxFill'].Visible = false","            end","","            if not Objects['CornerHolder'].Visible then","                Objects['CornerHolder'].Visible = true","            end","","            local GradTop = BoxesCfg['Gradients']['Top']","            local GradBot = BoxesCfg['Gradients']['Bot']","","            for i = 1, 8 do","                local Line = Objects['Line_' .. i]","                local Stroke = Line:FindFirstChildOfClass('UIStroke')","                local LayoutEntry = CornerLayout[i]","                local LPos, LSize, LAnchor, LRot = LayoutEntry[1], LayoutEntry[2], LayoutEntry[3], LayoutEntry[4]","","                Line.Position = LPos","                Line.Size = LSize","                Line.AnchorPoint = LAnchor","                Line.Rotation = LRot","                Line.BackgroundColor3 = GradTop","                Line.BackgroundTransparency = 0","                if Stroke then","                    Stroke.Color = GradTop","                end","                Line.Visible = true","            end","        else","            if Objects['CornerHolder'].Visible then","                Objects['CornerHolder'].Visible = false","            end","            for i = 1, 8 do","                if Objects['Line_' .. i].Visible then","                    Objects['Line_' .. i].Visible = false","                end","            end","","            if not Objects['BoxOutlineHolder'].Visible then","                Objects['BoxOutlineHolder'].Visible = true","            end","","            if not Objects['BoxInlineHolder'].Visible then","                Objects['BoxInlineHolder'].Visible = true","            end","","            local GradTop = BoxesCfg['Gradients']['Top']","            local GradBot = BoxesCfg['Gradients']['Bot']","","            if Data['LastGradTop'] ~= GradTop or Data['LastGradBot'] ~= GradBot then","                Objects['BoxInlineGradient'].Color = ColorSequence.new({","                    ColorSequenceKeypoint.new(0, GradTop),","                    ColorSequenceKeypoint.new(1, GradBot),","                })","                Data['LastGradTop'] = GradTop","                Data['LastGradBot'] = GradBot","            end","","            if BoxesCfg['Filled']['Enabled'] then","                if not Objects['BoxFill'].Visible then","                    Objects['BoxFill'].Visible = true","                end","","                local FillTop = BoxesCfg['Filled']['Top']","                local FillBot = BoxesCfg['Filled']['Bot']","                local FillT1 = BoxesCfg['Filled']['Transparency'][1]","                local FillT2 = BoxesCfg['Filled']['Transparency'][2]","","                if Data['LastFillTop'] ~= FillTop or Data['LastFillBot'] ~= FillBot then","                    Objects['BoxFillGradient'].Color = ColorSequence.new({","                        ColorSequenceKeypoint.new(0, FillTop),","                        ColorSequenceKeypoint.new(1, FillBot),","                    })","                    Data['LastFillTop'] = FillTop","                    Data['LastFillBot'] = FillBot","                end","","                if Data['LastFillT1'] ~= FillT1 or Data['LastFillT2'] ~= FillT2 then","                    Objects['BoxFillGradient'].Transparency = NumSeq({NumKey(0, FillT1), NumKey(1, FillT2)})","                    Data['LastFillT1'] = FillT1","                    Data['LastFillT2'] = FillT2","                end","            else","                if Objects['BoxFill'].Visible then","                    Objects['BoxFill'].Visible = false","                end","            end","        end","    else","        if Objects['BoxGlow'].ImageTransparency ~= 1 then","            Objects['BoxGlow'].ImageTransparency = 1","        end","","        if Objects['BoxOutlineHolder'].Visible then","            Objects['BoxOutlineHolder'].Visible = false","        end","","        if Objects['BoxInlineHolder'].Visible then","            Objects['BoxInlineHolder'].Visible = false","        end","","        if Objects['BoxFill'].Visible then","            Objects['BoxFill'].Visible = false","        end","","        if Objects['CornerHolder'].Visible then","            Objects['CornerHolder'].Visible = false","        end","","        for i = 1, 8 do","            if Objects['Line_' .. i].Visible then","                Objects['Line_' .. i].Visible = false","            end","        end","    end","","    if TextsCfg['Name']['Enabled'] then","        if not Objects['TargetName'].Visible then","            Objects['TargetName'].Visible = true","        end","","        local DisplayName = Player.DisplayName","","        if Data['LastDisplayName'] ~= DisplayName then","            Objects['TargetName'].Text = DisplayName","            Data['LastDisplayName'] = DisplayName","        end","","        local NameColor = TextsCfg['Name']['Color']","","        if Data['LastNameColor'] ~= NameColor then","            Objects['TargetName'].TextColor3 = NameColor","            Data['LastNameColor'] = NameColor","        end","    else","        if Objects['TargetName'].Visible then","            Objects['TargetName'].Visible = false","        end","    end","","    if TextsCfg['Distance']['Enabled'] then","        if not Objects['Distance'].Visible then","            Objects['Distance'].Visible = true","        end","","        if Data['LastDist'] ~= Distance then","            Objects['Distance'].Text = Format('%dst', Distance)","            Data['LastDist'] = Distance","        end","","        local DistColor = TextsCfg['Distance']['Color']","","        if Data['LastDistColor'] ~= DistColor then","            Objects['Distance'].TextColor3 = DistColor","            Data['LastDistColor'] = DistColor","        end","    else","        if Objects['Distance'].Visible then","            Objects['Distance'].Visible = false","        end","    end","","    local HealthCfg = Table['Bars']['Health Bar']","    local ArmorCfg = Table['Bars']['Armor Bar']","","    if HealthCfg['Enabled'] then","        local Health = Data['Health'] or 0","        local MaxHealth = Data['MaxHealth'] or 100","        local Ratio = Clamp(Health / MaxHealth, 0, 1)","","        if not Objects['LeftBarHolder'].Visible then","            Objects['LeftBarHolder'].Visible = true","        end","","        if not Objects['HealthBarOutline'].Visible then","            Objects['HealthBarOutline'].Visible = true","        end","","        if Data['LastRatio'] ~= Ratio then","            Objects['HealthBar'].Size = Dim2(1, 0, Ratio, 0)","            Data['LastRatio'] = Ratio","        end","","        local GradTop = HealthCfg['Top']","        local GradMid = HealthCfg['Mid']","        local GradBot = HealthCfg['Bot']","","        if Data['LastHealthTop'] ~= GradTop or Data['LastHealthMid'] ~= GradMid or Data['LastHealthBot'] ~= GradBot then","            Objects['HealthBarGradient'].Color = ColorSequence.new({","                ColorSequenceKeypoint.new(0, GradTop),","                ColorSequenceKeypoint.new(0.5, GradMid),","                ColorSequenceKeypoint.new(1, GradBot),","            })","            Data['LastHealthTop'] = GradTop","            Data['LastHealthMid'] = GradMid","            Data['LastHealthBot'] = GradBot","        end","","        if HealthCfg['Enabled'] then","            if not Objects['HealthBarText'].Visible then","                Objects['HealthBarText'].Visible = true","            end","","            local FlooredHealth = Floor(Health)","","            if Data['LastHealthFloor'] ~= FlooredHealth then","                Objects['HealthBarText'].Text = Format('%d', FlooredHealth)","                Objects['HealthBarText'].Position = Dim2(1, -10, 1 - Ratio, 1)","                Data['LastHealthFloor'] = FlooredHealth","            end","        else","            if Objects['HealthBarText'].Visible then","                Objects['HealthBarText'].Visible = false","            end","        end","    else","        if Objects['HealthBarOutline'].Visible then","            Objects['HealthBarOutline'].Visible = false","        end","","        if Objects['HealthBarText'].Visible then","            Objects['HealthBarText'].Visible = false","        end","","        if not ArmorCfg['Enabled'] then","            if Objects['LeftBarHolder'].Visible then","                Objects['LeftBarHolder'].Visible = false","            end","        end","    end","","    if ArmorCfg['Enabled'] then","        local Ratio = Clamp(Data['Armor'] / Data['MaxArmor'], 0, 1)","","        if not Objects['BottomBarHolder'].Visible then","            Objects['BottomBarHolder'].Visible = true","        end","","        if not Objects['ArmorBarOutline'].Visible then","            Objects['ArmorBarOutline'].Visible = true","        end","","        if Data['LastArmorRatio'] ~= Ratio then","            Objects['ArmorBar'].Size = Dim2(Ratio, 0, 1, 0)","            Data['LastArmorRatio'] = Ratio","        end","","        local GradTop = ArmorCfg['Top']","        local GradMid = ArmorCfg['Mid']","        local GradBot = ArmorCfg['Bot']","","        if Data['LastArmorTop'] ~= GradTop or Data['LastArmorMid'] ~= GradMid or Data['LastArmorBot'] ~= GradBot then","            Objects['ArmorBarGradient'].Color = ColorSequence.new({","                ColorSequenceKeypoint.new(0, GradTop),","                ColorSequenceKeypoint.new(0.5, GradMid),","                ColorSequenceKeypoint.new(1, GradBot),","            })","            Data['LastArmorTop'] = GradTop","            Data['LastArmorMid'] = GradMid","            Data['LastArmorBot'] = GradBot","        end","","        if Ratio \u003c 1 then","            if not Objects['ArmorBarText'].Visible then","                Objects['ArmorBarText'].Visible = true","            end","","            local FlooredArmor = Floor(Data['Armor'])","","            if Data['LastArmorFloor'] ~= FlooredArmor then","                Objects['ArmorBarText'].Text = Format('%d', FlooredArmor)","                Data['LastArmorFloor'] = FlooredArmor","            end","        else","            if Objects['ArmorBarText'].Visible then","                Objects['ArmorBarText'].Visible = false","            end","        end","    else","        if Objects['BottomBarHolder'].Visible then","            Objects['BottomBarHolder'].Visible = false","        end","","        if Objects['ArmorBarOutline'].Visible then","            Objects['ArmorBarOutline'].Visible = false","        end","","        if Objects['ArmorBarText'].Visible then","            Objects['ArmorBarText'].Visible = false","        end","    end","","    local WeaponCfg = TextsCfg['Weapon']","","    if WeaponCfg['Enabled'] then","        if not Objects['Weapon'].Visible then","            Objects['Weapon'].Visible = true","        end","","        local CurrentTool = Data['CurrentTool'] or 'none'","","        if Data['LastWeapon'] ~= CurrentTool then","            Objects['Weapon'].Text = CurrentTool","            Data['LastWeapon'] = CurrentTool","        end","","        local WeaponColor = WeaponCfg['Color']","","        if Data['LastWeaponColor'] ~= WeaponColor then","            Objects['Weapon'].TextColor3 = WeaponColor","            Data['LastWeaponColor'] = WeaponColor","        end","    else","        if Objects['Weapon'].Visible then","            Objects['Weapon'].Visible = false","        end","    end","end","","do","    Library:CreateThreads('Renderer', RunService.RenderStepped, function()","        if not Table['Enabled'] then","            for _, Data in Library['Cache'] do","                if Data['Objects']['TargetHolder'].Visible then","                    Data['Objects']['TargetHolder'].Visible = false","                end;","            end;","            return","        end;","","        local Now = os.clock();","","        if Now - Updates \u003c Frame then","            return;","        end;","","        Updates = Now;","        CameraPosition = Camera.CFrame.Position;","","        for Player, Data in Library['Cache'] do","            Library:Update(Player, Data)","        end","    end)","end","","do","    for _, Player in Players:GetPlayers() do","        Library:AddTarget(Player)","    end","","    Library:CreateThreads('PlayerAdded', Players.PlayerAdded, function(Player)","        Library:AddTarget(Player)","    end)","","    Library:CreateThreads('PlayerRemoving', Players.PlayerRemoving, function(Player)","        Library:RemoveTarget(Player)","    end)","end","","do","    function Library:Unload()","        for Player in self['Cache'] do","            self:RemoveTarget(Player);","        end;","","        for _, Conn in self['Connections'] do","            Conn:Disconnect();","        end;","","        Clear(self['Connections']);","","        for _, Conn in self['Threads'] do","            Conn:Disconnect();","        end;","","        Clear(self['Threads']);","","        if self['Holder'] then","            self['Holder']:Destroy();","            self['Holder'] = nil;","        end;","","        Clear(self['Cache']);","    end","end","","","-------------------------------------------------","-- UI + LEGIT + WEATHER","-------------------------------------------------","local ui_lib, themes = loadstring(game:HttpGet(\"https://raw.githubusercontent.com/8sn1/lib/refs/heads/main/papi\"))()","local dim2 = UDim2.new","","local Lighting = game:GetService(\"Lighting\")","local SoundService = game:GetService(\"SoundService\")","local TweenService = game:GetService(\"TweenService\")","local UIS = game:GetService(\"UserInputService\")","local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")","local Table = Library.Table","","-- blur","local blur, menuOpen = nil, true","local function createBlur()","    if blur and blur.Parent then return end","    blur = Instance.new(\"BlurEffect\")","    blur.Name = \"void_blur\"","    blur.Size = 24","    blur.Parent = Lighting","end","local function killBlur()","    if blur then blur:Destroy() blur = nil end","    for _, v in ipairs(Lighting:GetChildren()) do","        if v:IsA(\"BlurEffect\") then v:Destroy() end","    end","end","local function setMenu(state)","    menuOpen = state","    for _, gui in ipairs(ui_lib.guis or {}) do","        if gui and gui.Parent then gui.Enabled = state end","    end","    if state then createBlur() else killBlur() end","end","UIS.InputBegan:Connect(function(input, gpe)","    if gpe then return end","    if input.KeyCode == Enum.KeyCode.Insert then","        setMenu(not menuOpen)","    end","end)","","local window = ui_lib:window({","    name = \"dan ffa main script\",","    size = dim2(0, 420, 0, 580)","})","","local Legit = window:tab({ name = \"legit\" })","local Visuals = window:tab({ name = \"visuals\" })","local Misc = window:tab({ name = \"misc\" })","","local legitCol = Legit:column()","local visCol = Visuals:column()","local miscCol = Misc:column()","","-------------------------------------------------","-- LEGIT","-------------------------------------------------","local S = {","    aim = false,","    wallcheck = false,","    teamcheck = false,","    showFov = true,","    fov = 300,","    hit = \"Head\",","    chams = false","}","","local silentSec = legitCol:section({ name = \"silent aim\", toggle = false })","silentSec:toggle({ name = \"enabled\", flag = \"sa_enabled\", default = false, callback = function(v) S.aim = v end })","silentSec:toggle({ name = \"show fov\", flag = \"sa_showfov\", default = true, callback = function(v) S.showFov = v end })","silentSec:slider({ name = \"fov\", flag = \"sa_fov\", min = 10, max = 800, default = 300, interval = 1, callback = function(v) S.fov = v end })","silentSec:dropdown({ name = \"hit part\", flag = \"sa_hitpart\", items = {\"Head\",\"HumanoidRootPart\",\"UpperTorso\",\"LowerTorso\"}, default = \"Head\", callback = function(v) S.hit = v end })","silentSec:toggle({ name = \"wall check\", flag = \"sa_wallcheck\", default = false, callback = function(v) S.wallcheck = v end })","silentSec:toggle({ name = \"team check\", flag = \"sa_teamcheck\", default = false, callback = function(v) S.teamcheck = v end })","","local chamsSec = legitCol:section({ name = \"chams\", toggle = false })","chamsSec:toggle({ name = \"white chams\", flag = \"sa_chams\", default = false, callback = function(v) S.chams = v end })","","local fovCircle = Drawing.new(\"Circle\")","fovCircle.Thickness = 1","fovCircle.NumSides = 64","fovCircle.Filled = false","fovCircle.Color = Color3.fromRGB(255,255,255)","fovCircle.Visible = false","","local aLine = Drawing.new(\"Line\")","aLine.Thickness = 1","aLine.Color = Color3.fromRGB(0,255,100)","aLine.Visible = false","","local function isVisible(origin, part)","    if not S.wallcheck then return true end","    local params = RaycastParams.new()","    params.FilterType = Enum.RaycastFilterType.Blacklist","    params.FilterDescendantsInstances = {LocalPlayer.Character}","    local result = Workspace:Raycast(origin, part.Position - origin, params)","    return not result or result.Instance:IsDescendantOf(part.Parent)","end","","local function findTarget()","    if not S.aim then return nil end","    local best, bestDist = nil, S.fov","    local mouse = UIS:GetMouseLocation()","    local origin = Camera.CFrame.Position","    for _, p in ipairs(Players:GetPlayers()) do","        if p == LocalPlayer then continue end","        if S.teamcheck and p.Team and LocalPlayer.Team and p.Team == LocalPlayer.Team then continue end","        local c = p.Character","        if not c then continue end","        local part = c:FindFirstChild(S.hit)","        if not part then continue end","        local hum = c:FindFirstChildOfClass(\"Humanoid\")","        if hum and hum.Health \u003c= 0 then continue end","        local state = c:FindFirstChild(\"State\")","        if state then","            local down, dead = state:FindFirstChild(\"Down\"), state:FindFirstChild(\"Dead\")","            if (down and down.Value) or (dead and dead.Value) then continue end","        end","        if not isVisible(origin, part) then continue end","        local screenPos, onScreen = Camera:WorldToViewportPoint(part.Position)","        if not onScreen then continue end","        local dist = (Vector2.new(mouse.X, mouse.Y) - Vector2.new(screenPos.X, screenPos.Y)).Magnitude","        if dist \u003c= S.fov and dist \u003c bestDist then","            bestDist = dist","            best = p","        end","    end","    return best","end","","pcall(function()","    local GunHandler = require(ReplicatedStorage.Modules.Guns.GunHandler)","    local oldShoot = GunHandler.Shoot","    GunHandler.Shoot = function(p1, p2, p3, p4, p5, p6, p7, p8)","        if S.aim and p1 == LocalPlayer and p4 then","            local tgt = findTarget()","            if tgt and tgt.Character then","                local part = tgt.Character:FindFirstChild(S.hit)","                if part then p4 = part.Position end","            end","        end","        return oldShoot(p1, p2, p3, p4, p5, p6, p7, p8)","    end","end)","","task.spawn(function()","    while task.wait(0.35) do","        for _, p in ipairs(Players:GetPlayers()) do","            if p == LocalPlayer then continue end","            local c = p.Character","            if not c then continue end","            local hl = c:FindFirstChild(\"WhiteChams_HL\")","            if S.chams then","                if not hl then","                    hl = Instance.new(\"Highlight\")","                    hl.Name = \"WhiteChams_HL\"","                    hl.Adornee = c","                    hl.FillColor = Color3.fromRGB(255,255,255)","                    hl.OutlineColor = Color3.fromRGB(255,255,255)","                    hl.FillTransparency = 0.3","                    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop","                    hl.Parent = c","                end","            elseif hl then","                hl:Destroy()","            end","        end","    end","end)","","RunService.RenderStepped:Connect(function()","    local mouse = UIS:GetMouseLocation()","    if S.showFov and S.aim then","        fovCircle.Visible = true","        fovCircle.Position = Vector2.new(mouse.X, mouse.Y)","        fovCircle.Radius = S.fov","    else","        fovCircle.Visible = false","    end","    local tgt = findTarget()","    if S.aim and tgt and tgt.Character then","        local part = tgt.Character:FindFirstChild(S.hit)","        if part then","            local sp, on = Camera:WorldToViewportPoint(part.Position)","            if on then","                aLine.Visible = true","                aLine.From = Vector2.new(mouse.X, mouse.Y)","                aLine.To = Vector2.new(sp.X, sp.Y)","            else aLine.Visible = false end","        else aLine.Visible = false end","    else aLine.Visible = false end","end)","","-------------------------------------------------","-- VISUALS (single column)","-------------------------------------------------","local globalSec = visCol:section({ name = \"global\", toggle = false })","globalSec:toggle({ name = \"enable esp\", flag = \"esp_enabled\", default = true, callback = function(v) Table.Enabled = v end })","globalSec:toggle({","    name = \"show local\",","    flag = \"esp_local\",","    default = false,","    callback = function(v)","    