"    if not emitter then return end","    local w = getgenv().currentWeather","    if w == \"rain\" then","        emitter.Texture = WeatherTextures.Rain","        emitter.Rate = getgenv().rainAmount","        emitter.Speed = NumberRange.new(40, 60)","        emitter.Lifetime = NumberRange.new(1.5, 2.5)","        emitter.Size = NumberSequence.new(0.4, 0.8)","        emitter.Transparency = NumberSequence.new(0.2, 0.6)","        emitter.EmissionDirection = Enum.NormalId.Bottom","        emitter.SpreadAngle = Vector2.new(15, 15)","        emitter.Acceleration = Vector3.new(0, -30, 0)","        emitter.Orientation = Enum.ParticleOrientation.FacingCamera","    elseif w == \"snow\" then","        emitter.Texture = WeatherTextures.Snow","        emitter.Rate = getgenv().snowAmount","        emitter.Speed = NumberRange.new(5, 12)","        emitter.Lifetime = NumberRange.new(3, 5)","        emitter.Size = NumberSequence.new({","            NumberSequenceKeypoint.new(0, 0.3),","            NumberSequenceKeypoint.new(0.5, 0.5),","            NumberSequenceKeypoint.new(1, 0.3)","        })","        emitter.Transparency = NumberSequence.new(0.1, 0.5)","        emitter.EmissionDirection = Enum.NormalId.Bottom","        emitter.SpreadAngle = Vector2.new(40, 40)","        emitter.Acceleration = Vector3.new(0, -5, 0)","        emitter.Orientation = Enum.ParticleOrientation.FacingCamera","    else","        emitter.Texture = WeatherTextures.Autumn","        emitter.Rate = getgenv().autumnAmount","        emitter.Speed = NumberRange.new(8, 18)","        emitter.Lifetime = NumberRange.new(2, 4)","        emitter.Size = NumberSequence.new(0.6, 1.0)","        emitter.Transparency = NumberSequence.new(0.1, 0.5)","        emitter.Orientation = Enum.ParticleOrientation.VelocityPerpendicular","        emitter.EmissionDirection = Enum.NormalId.Bottom","        emitter.SpreadAngle = Vector2.new(50, 50)","        emitter.Acceleration = Vector3.new(0, -8, 0)","    end","end","","local function createWeather()","    local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()","    local head = char:FindFirstChild(\"Head\") or char:WaitForChild(\"Head\", 5)","    if not head then return nil end","","    local part = Instance.new(\"Part\")","    part.Name = \"void_weather_part\"","    part.Size = Vector3.new(40, 1, 40)","    part.Transparency = 1","    part.CanCollide = false","    part.CanQuery = false","    part.CanTouch = false","    part.Anchored = false","    part.Massless = true","    part.Parent = Workspace","","    local weld = Instance.new(\"WeldConstraint\")","    weld.Part0 = head","    weld.Part1 = part","    weld.Parent = part","    part.CFrame = head.CFrame * CFrame.new(0, 25, 0)","","    local emitter = Instance.new(\"ParticleEmitter\")","    emitter.Enabled = true","    emitter.Parent = part","    applyEmitterSettings(emitter)","","    getgenv().weatherEmitter = emitter","    return part","end","","local function startWeather()","    if getgenv().weatherPart then","        pcall(function() getgenv().weatherPart:Destroy() end)","        getgenv().weatherPart = nil","        getgenv().weatherEmitter = nil","    end","    local p = createWeather()","    if p then getgenv().weatherPart = p end","end","","local function stopWeather()","    if getgenv().weatherPart then","        pcall(function() getgenv().weatherPart:Destroy() end)","        getgenv().weatherPart = nil","        getgenv().weatherEmitter = nil","    end","end","","local function restartWeather()","    if getgenv().weatherEnabled then","        stopWeather()","        task.wait()","        startWeather()","    end","end","","local function updateDensity()","    if getgenv().weatherEmitter then","        applyEmitterSettings(getgenv().weatherEmitter)","    elseif getgenv().weatherEnabled then","        restartWeather()","    end","end","","local function stopWeatherSound()","    if getgenv().weatherSound then","        pcall(function() getgenv().weatherSound:Stop() getgenv().weatherSound:Destroy() end)","        getgenv().weatherSound = nil","        getgenv().currentWeatherSound = nil","    end","end","","local function playWeatherSound(name)","    local id = weatherSounds[name]","    if not id then return end","    if getgenv().currentWeatherSound == name then stopWeatherSound() return end","    stopWeatherSound()","    getgenv().weatherSound = Instance.new(\"Sound\")","    getgenv().weatherSound.SoundId = \"rbxassetid://\" .. id","    getgenv().weatherSound.Looped = true","    getgenv().weatherSound.Volume = 10","    getgenv().weatherSound.Parent = SoundService","    getgenv().weatherSound:Play()","    getgenv().currentWeatherSound = name","end","","weathersec:toggle({ name = \"weather\", flag = \"weather_tgl\", default = false, callback = function(state)","    getgenv().weatherEnabled = state","    if state then startWeather() else stopWeather() end","end })","","weathersec:dropdown({ name = \"weather type\", flag = \"weather_type\", items = {\"autumn\",\"rain\",\"snow\"}, default = \"autumn\", callback = function(value)","    getgenv().currentWeather = value","    if getgenv().weatherEnabled then restartWeather() end","end })","","weathersec:slider({","    name = \"rain amount\",","    flag = \"rain_amount\",","    min = 50, max = 8000, default = 2000, interval = 50,","    callback = function(v)","        getgenv().rainAmount = v","        if getgenv().currentWeather == \"rain\" then updateDensity() end","    end","})","","weathersec:slider({","    name = \"snow amount\",","    flag = \"snow_amount\",","    min = 20, max = 3000, default = 400, interval = 20,","    callback = function(v)","        getgenv().snowAmount = v","        if getgenv().currentWeather == \"snow\" then updateDensity() end","    end","})","","weathersec:slider({","    name = \"autumn amount\",","    flag = \"autumn_amount\",","    min = 20, max = 3000, default = 300, interval = 20,","    callback = function(v)","        getgenv().autumnAmount = v","        if getgenv().currentWeather == \"autumn\" then updateDensity() end","    end","})","","weathersec:toggle({ name = \"weather audio\", flag = \"weather_audio_tgl\", default = false, callback = function(state)","    getgenv().weatherAudioEnabled = state","    if not state then stopWeatherSound() end","end })","weathersec:dropdown({ name = \"sound type\", flag = \"weather_audio_type\", items = {\"rain\",\"thunder\"}, default = \"rain\", callback = function(value)","    if getgenv().weatherAudioEnabled then playWeatherSound(value) end","end })","weathersec:slider({ name = \"volume\", flag = \"weather_audio_volume\", min = 0, max = 10, default = 10, interval = 1, callback = function(v)","    if getgenv().weatherSound then getgenv().weatherSound.Volume = v end","end })","","LocalPlayer.CharacterAdded:Connect(function()","    task.wait(0.5)","    if getgenv().weatherEnabled then restartWeather() end","end)","","-------------------------------------------------","-- FINAL","-------------------------------------------------","Legit.open_tab()","task.wait(0.25)","setMenu(true)","","ui_lib:config_list_update()","for index, value in themes.preset do","    pcall(function() ui_lib:update_theme(index, value) end)","end","task.wait()","ui_lib.old_config = ui_lib:get_config()","","ui_lib:notification({ text = \"dan ffa main script loaded\", time = 2 })"],"stylingDirectives":[[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[],[